head.script:
scwin.trigger1_onclick = function(e) {
	var tmpOpt = {
		id: "submission123",
		ref: "",
		target: "data:json,dataList1",
		action: "/data/subMission_Abort_WPF-1522_(WSQ-2485)_sleep.jsp",
		mediatype: "application/json",
		processMsg: "처리중입니다.",
		abortTrigger: "true",
		submitDoneHandler: function(e) {
			localStorage.setItem('showAlert', 'true');
		}
	};
	$p.createSubmission(tmpOpt);
	$p.executeSubmission("submission123");
};
scwin.__isCreatedProcessMsg = function() {
	return ((j) => j.length ? j : $('#mf____processbar2_i'))($('#___processbar2_i')).length > 0;
};
scwin.__isCanceledProcess = function() {
	return ((j) => j.length ? j : $('#mf____processbar2_i'))($('#___processbar2_i')).css("display") == "none";
};
scwin.__isCancelButton = function() {
	var iframe = (document.getElementById('___processbar2_i') || document.getElementById('mf____processbar2_i')).childNodes[0];
	var innerDoc = iframe.contentDocument || iframe.contentWindow.document;
	var button = innerDoc.getElementById("abortButton");
	if (button) {
		return true;
	}
	return false;
};
scwin.__clickCancelButton = function() {
	var iframe = (document.getElementById('___processbar2_i') || document.getElementById('mf____processbar2_i')).childNodes[0];
	var innerDoc = iframe.contentDocument || iframe.contentWindow.document;
	var button = innerDoc.getElementById("abortButton");
	return button.click();
};
scwin.checkVal = function() {
	return localStorage.getItem('showAlert') == 'true';
};
